package es.vargontoc.storyteller.application.service;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
import java.util.*; import org.junit.jupiter.api.Test;
import es.vargontoc.storyteller.application.ports.out.external.CharacterAgent; import es.vargontoc.storyteller.application.ports.out.external.CharacterImageConditionPort; import es.vargontoc.storyteller.application.ports.out.persistence.*; import es.vargontoc.storyteller.domain.model.CatalogCharacter; import es.vargontoc.storyteller.infrastructure.validations.CatalogCharacterAgentResultValidator;
class CharacterCatalogQueriesTest {
 private final CatalogCharacter character=new CatalogCharacter(7L,"Luna","curiosa","zorra","fox",List.of("orange"));
 private CharacterCatalogService service(CatalogCharacterRepository r,boolean portrait,boolean pending){CharacterImageConditionPort images=mock(CharacterImageConditionPort.class);when(images.hasApprovedPortrait(anyLong())).thenReturn(portrait);when(images.hasGeneratedImages(anyLong())).thenReturn(false);CatalogCharacterPendingReviewReader reviews=mock(CatalogCharacterPendingReviewReader.class);when(reviews.hasPendingReview(anyLong())).thenReturn(pending);return new CharacterCatalogService(mock(CharacterAgent.class),r,new CatalogCharacterAgentResultValidator(),reviews,Optional.of(images));}
 @Test void listsEmptyCatalog(){var r=mock(CatalogCharacterRepository.class);when(r.findAll()).thenReturn(List.of());assertTrue(service(r,false,false).list().isEmpty());}
 @Test void derivesDraftAndPending(){var r=mock(CatalogCharacterRepository.class);when(r.findAll()).thenReturn(List.of(character));var view=service(r,false,true).list().getFirst();assertTrue(view.draft());assertTrue(view.pendingReview());}
 @Test void derivesPublishedAndNoPending(){var r=mock(CatalogCharacterRepository.class);when(r.findById(7L)).thenReturn(character);var view=service(r,true,false).get(7L);assertFalse(view.draft());assertFalse(view.pendingReview());}
 @Test void detailContainsAllTextFields(){var r=mock(CatalogCharacterRepository.class);when(r.findById(7L)).thenReturn(character);var view=service(r,true,false).get(7L);assertEquals("Luna",view.name());assertEquals("curiosa",view.narrativeDescription());assertEquals("zorra",view.visualDescription());}
 @Test void renameOnlyWritesCatalogMaster(){var r=mock(CatalogCharacterRepository.class);when(r.rename(7L,"Luna nueva")).thenReturn(new CatalogCharacter(7L,"Luna nueva","curiosa","zorra","fox",List.of()));var result=service(r,true,false).rename(7L,"Luna nueva");assertEquals("Luna nueva",result.name());verify(r).rename(7L,"Luna nueva");verifyNoMoreInteractions(r);}
}
